(4792036, 692169, 67152, '<td valign="top">nice macro shot - and a good tribute to the other lightbulb/ plant shots here at dpc</td>', 'nice macro shot - and a good tribute to the other lightbulb/ plant shots here at dpc', '2008-06-30 17:33:51.000000', NULL, 1),
(4792051, 693326, 67152, '<td valign="top">a very cool use of recycled items - a bit overexposed due to the brightness above - but it meets the challenge...</td>', 'a very cool use of recycled items - a bit overexposed due to the brightness above - but it meets the challenge...', '2008-06-30 17:42:07.000000', NULL, 1),
(4792055, 691689, 67152, '<td valign="top">a very unusual take on the challenge - very well delivered and extremely dramatic (or it is the model).  To be honest, when I looked at the thumb, I thought it was a shoehorn.  Nice work overall...</td>', 'a very unusual take on the challenge - very well delivered and extremely dramatic (or it is the model).  To be honest, when I looked at the thumb, I thought it was a shoehorn.  Nice work overall...', '2008-06-30 17:43:00.000000', NULL, 1),
