(4799029, 691937, 52500, '<td valign="top">Nice and sharp.  Interesting angle showing some grass on the outside and the new plants on the inside.</td>', 'Nice and sharp.  Interesting angle showing some grass on the outside and the new plants on the inside.', '2008-07-02 16:31:30.000000', NULL, 1),
