(4807639, 692574, 83313, '<td valign="top">Hmmm. A bit unusual, but how else can one recycle a cookie package?</td>', 'Hmmm. A bit unusual, but how else can one recycle a cookie package?', '2008-07-06 21:12:27.000000', NULL, 1),
(4807641, 692971, 83313, '<td valign="top">Midday sun is a little hard on this pic, otherwise I like it.</td>', 'Midday sun is a little hard on this pic, otherwise I like it.', '2008-07-06 21:13:48.000000', NULL, 1),
